const $=id=>document.getElementById(id); const types=[['shelf','Grocery shelf','▤','', 'Grocery'],['produce','Produce display','🥬','', 'Produce'],['fridge','Refrigerated case','▥','blue','Dairy'],['frozen','Frozen section','❄','blue','Frozen'],['bakery','Bakery department','🥖','yellow','Bakery'],['deli','Deli & prepared','🥪','pink','Deli'],['beverage','Beverage display','♧','blue','Beverages'],['promo','Promotional display','✿','pink','Promotions'],['register','Checkout register','▣','yellow small','Checkout'],['self','Self-checkout','▣','blue small','Checkout'],['carts','Carts & baskets','🛒','pink small','Supplies']];
let items=[],selected=null,people=[],heat={},stats={},running=false,speed=1,seconds=0,last=0,spawn=0,showHeat=false,baseline=null,dragType=null; const initial=[['produce',18,22],['bakery',50,16],['fridge',82,20],['shelf',30,43],['shelf',54,43],['frozen',80,45],['beverage',25,67],['promo',52,66],['register',72,82],['self',86,82],['carts',15,83]]; const names=['Apples','Fresh bread','Milk','Frozen meals','Sandwiches','Sparkling water','Snack mix'];
function type(id){return types.find(x=>x[0]===id)} function add(id,x=50,y=50){items.push({id:Date.now()+Math.random(),type:id,x:Math.max(6,Math.min(94,x)),y:Math.max(6,Math.min(94,y)),rotation:0,open:true});selected=items.at(-1).id;render();save()} function save(){localStorage.setItem('marketmaker-layout',JSON.stringify(items))} function renderPalette(){$('palette').innerHTML=types.map(t=>`<button class="palette-item" draggable="true" data-type="${t[0]}"><span class="palette-icon">${t[2]}</span><span>${t[1]}</span></button>`).join('');document.querySelectorAll('.palette-item').forEach(el=>{el.onclick=()=>add(el.dataset.type,35+Math.random()*30,35+Math.random()*30);el.ondragstart=e=>{dragType=el.dataset.type;e.dataTransfer.setData('text/plain',dragType)}})}
function render(){ $('objects').innerHTML=items.map(o=>{let t=type(o.type);return `<div class="floor-object ${t[3]} ${selected===o.id?'selected':''}" data-id="${o.id}" style="left:${o.x}%;top:${o.y}%;--rotation:${o.rotation}deg" title="${t[1]}${!o.open?' (closed)':''}"><span class="obj-icon">${t[2]}</span><span>${t[1]}${!o.open?' · CLOSED':''}</span></div>`}).join(''); $('itemCount').textContent=items.length+' items placed'; let s=items.find(o=>o.id===selected);$('selectedName').textContent=s?type(s.type)[1]:'Select an item to edit'; document.querySelectorAll('.floor-object').forEach(el=>{el.onpointerdown=e=>{e.preventDefault();let id=Number(el.dataset.id);selected=id;render();let target=items.find(o=>o.id===id); const move=ev=>{let r=$('floor').getBoundingClientRect(); target.x=Math.max(5,Math.min(95,(ev.clientX-r.left)/r.width*100));target.y=Math.max(5,Math.min(95,(ev.clientY-r.top)/r.height*100));render()};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);save()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)}});}
$('floor').ondragover=e=>e.preventDefault();$('floor').ondrop=e=>{e.preventDefault();let r=$('floor').getBoundingClientRect();add(e.dataTransfer.getData('text/plain')||dragType,(e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100)};$('toggle').onclick=()=>{let o=items.find(x=>x.id===selected);if(o&&['register','self'].includes(o.type)){o.open=!o.open;render();save()}};$('sample').onclick=()=>{items=initial.map(([type,x,y],i)=>({id:Date.now()+i,type,x,y,rotation:0,open:true}));selected=null;render();save()};$('rotate').onclick=()=>{let o=items.find(x=>x.id===selected);if(o){o.rotation=(o.rotation+90)%180;render();save()}};$('remove').onclick=()=>{items=items.filter(x=>x.id!==selected);selected=null;render();save()};$('clear').onclick=()=>{items=[];selected=null;render();save()};
function resetStats(){stats={revenue:0,profit:0,visitors:0,completed:0,wait:0,satisfaction:0,impulses:0,sales:{},products:{}};seconds=0;people=[];heat={};spawn=0;update();renderPeople();renderHeat()} resetStats();
function customer(){let departments=items.filter(o=>!['register','self','carts'].includes(o.type));if(!departments.length)return;let behavior=['Weekly shop','Specific item','Quick lunch','Promotion browser','Impulse shopper'][Math.floor(Math.random()*5)];let choices=behavior==='Quick lunch'?departments.filter(o=>['deli','bakery','beverage'].includes(o.type)):behavior==='Promotion browser'?departments.filter(o=>o.type==='promo'):departments; if(!choices.length)choices=departments;let n=behavior==='Weekly shop'?4:behavior==='Specific item'?1:2;let targets=Array.from({length:n},()=>choices[Math.floor(Math.random()*choices.length)]);let registers=items.filter(o=>['register','self'].includes(o.type)&&o.open);let reg=registers.sort((a,b)=>people.filter(p=>p.register===a.id).length-people.filter(p=>p.register===b.id).length)[0];people.push({x:50,y:98,targets,phase:'shop',register:reg?.id,wait:0,basket:0,behavior,color:['#db9d8e','#739d80','#d7ba75','#8c9cb1','#b493a6'][Math.floor(Math.random()*5)]});stats.visitors++}
function tick(dt){seconds+=dt;let demand=$('demand').value==='High'?1.5:$('demand').value==='Low'?.6:1;let day=$('day').value==='Holiday rush'?1.8:$('day').value==='Weekend'?1.3:1;spawn+=dt*demand*day;if(spawn>5){spawn=0;customer()}let registers=items.filter(o=>['register','self'].includes(o.type)&&o.open);for(let p of people){let target=p.phase==='shop'?p.targets[0]:p.phase==='checkout'?items.find(o=>o.id===p.register):{x:50,y:99};if(!target){if(p.phase==='shop'){p.phase='checkout';continue}if(p.phase==='checkout'){p.wait+=dt;if(registers.length){p.register=registers[0].id}else if(p.wait>25){p.phase='exit'}continue}}let dx=target.x-p.x,dy=target.y-p.y,dist=Math.hypot(dx,dy),step=dt*7;if(dist>step){p.x+=dx/dist*step;p.y+=dy/dist*step}else if(p.phase==='shop'){p.x=target.x;p.y=target.y;let discount=+$('discount').value,price=+$('price').value,stock=+$('inventory').value;let chance=Math.max(.1,Math.min(.95,.65+discount/150-price/150))*stock/100;if(Math.random()<chance){let amount=(5+Math.random()*14)*(1+price/100)*(1-discount/100);p.basket+=amount;let dept=type(target.type)[4];stats.sales[dept]=(stats.sales[dept]||0)+amount;let product=names[Math.floor(Math.random()*names.length)];stats.products[product]=(stats.products[product]||0)+1;if(target.type==='promo'||p.behavior==='Impulse shopper'){stats.impulses++}}p.targets.shift();if(!p.targets.length)p.phase='checkout'}else if(p.phase==='checkout'){p.wait+=dt;let q=people.filter(q=>q!==p&&q.phase==='checkout'&&q.register===p.register).length;let service=2+q*2/Math.max(1,+$('staff').value/2);if(p.wait>service){stats.revenue+=p.basket;stats.completed++;stats.wait+=p.wait;stats.satisfaction+=Math.max(20,Math.min(100,94-p.wait*2-Math.max(0,people.length-items.length)*2+(+$('discount').value)/3));p.phase='exit'}}else p.done=true;let key=Math.floor(p.x/10)+','+Math.floor(p.y/10);heat[key]=(heat[key]||0)+dt}people=people.filter(p=>!p.done);stats.profit=stats.revenue*(.28-(+$('discount').value)/200)-seconds/60*(+$('expense').value+(+$('staff').value)*.7);renderPeople();if(showHeat)renderHeat();update()}
function renderPeople(){$('customers').innerHTML=people.map(p=>`<div class="customer" title="${p.behavior}" style="left:${p.x}%;top:${p.y}%;background:${p.color}"></div>`).join('')}function renderHeat(){let max=Math.max(1,...Object.values(heat));$('heatlayer').innerHTML=showHeat?Object.entries(heat).map(([k,v])=>{let [x,y]=k.split(',').map(Number),ratio=v/max,color=ratio>.8?'#e75145':ratio>.6?'#f29b4b':ratio>.4?'#f4d663':ratio>.2?'#89c974':'#70b7d6';return `<div class="heat-cell" style="left:${x*10}%;top:${y*10}%;width:15%;height:15%;background:${color}"></div>`}).join(''):''}
function update(){let money=n=>'$'+n.toFixed(2);$('revenue').textContent=money(stats.revenue);$('profit').textContent=money(stats.profit);$('visitors').textContent=stats.visitors;$('satisfaction').textContent=stats.completed?Math.round(stats.satisfaction/stats.completed)+'%':'—';$('wait').textContent=stats.completed?(stats.wait/stats.completed).toFixed(1)+'s':'—';$('spend').textContent=money(stats.completed?stats.revenue/stats.completed:0);$('impulses').textContent=stats.impulses;$('congestion').textContent=people.length>12?'High':people.length>6?'Moderate':'Low';$('topProduct').textContent=Object.entries(stats.products).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—';$('clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(Math.floor(seconds%60)).padStart(2,'0');let rows=Object.entries(stats.sales).sort((a,b)=>b[1]-a[1]).slice(0,5),max=Math.max(1,...rows.map(x=>x[1]));$('bars').innerHTML=rows.length?rows.map(([name,val])=>`<div class="bar-row"><span>${name}</span><div class="bar-track"><div class="bar-fill" style="width:${val/max*100}%"></div></div><b>$${Math.round(val)}</b></div>`).join(''):'<div class="empty-bars">Run your market to see sales bloom.</div>';$('insightText').textContent=!items.some(x=>['register','self'].includes(x.type))?'Add a checkout so shoppers can complete their purchases.':people.length>10?'Your market is getting busy. More checkouts and staff can reduce waits.':'Place produce near the entrance to welcome shoppers with freshness.'}
function loop(t){if(running){if(last)tick(Math.min(.15,(t-last)/1000)*speed);last=t}else last=0;requestAnimationFrame(loop)}requestAnimationFrame(loop);$('start').onclick=()=>{running=!running;$('start').innerHTML=running?'Ⅱ &nbsp; Pause simulation':'▶ &nbsp; '+(seconds?'Resume simulation':'Start simulation');$('statusText').textContent=running?'Simulation running':'Simulation paused';$('modeDot').textContent=running?'● LIVE':''};$('reset').onclick=()=>{running=false;$('start').innerHTML='▶ &nbsp; Start simulation';$('statusText').textContent='Ready to create';$('modeDot').textContent='';resetStats()};$('heat').onclick=()=>{showHeat=!showHeat;$('heat').classList.toggle('active',showHeat);renderHeat()};document.querySelectorAll('.speed').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;document.querySelectorAll('.speed').forEach(x=>x.classList.toggle('active',x===b))});['price','discount','staff','inventory','expense'].forEach(id=>$(id).oninput=()=>{$(id+'Out').textContent=(id==='expense'?'$':'')+$(id).value+(['price','discount','inventory'].includes(id)?'%':'')});$('size').onchange=()=>{$('dimensions').textContent=$('size').value==='18'?'18 × 14':$('size').value==='30'?'30 × 22':'24 × 18';$('floor').style.backgroundSize=($('size').value==='18'?30:$('size').value==='30'?19:24)+'px '+($('size').value==='18'?30:$('size').value==='30'?19:24)+'px'};
function modal(html){$('modalContent').innerHTML=html;$('modal').classList.remove('hidden')}$('closeModal').onclick=()=>$('modal').classList.add('hidden');$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').classList.add('hidden')};$('help').onclick=()=>modal('<span class="section-kicker">WELCOME TO MARKETMAKER</span><h2>A little guide to your market</h2><p>Drag an item from the toolbox onto the floor, or tap it to add one. Move items by dragging them, then select one to rotate or remove it.</p><p>Start the simulation to watch shoppers browse and check out. Use the heatmap and insights to see how your decisions play out. Change the scenario and operations to experiment, then save a run to compare it with your next layout.</p><p>All results are illustrative estimates based on simplified rules, not real retail data.</p>');$('compare').onclick=()=>{let current={revenue:stats.revenue,profit:stats.profit,customers:stats.visitors,satisfaction:stats.completed?stats.satisfaction/stats.completed:0,wait:stats.completed?stats.wait/stats.completed:0,items:items.length};let row=(label,key,format)=>`<tr><td>${label}</td><td>${baseline?format(baseline[key]):'—'}</td><td>${format(current[key])}</td></tr>`;modal(`<span class="section-kicker">EXPERIMENT & LEARN</span><h2>Compare your markets</h2><p>Save this run as your baseline, then change your layout and run another simulation.</p><table class="compare-table"><tr><th>MEASURE</th><th>BASELINE</th><th>CURRENT RUN</th></tr>${row('Revenue','revenue',x=>'$'+x.toFixed(2))}${row('Profit','profit',x=>'$'+x.toFixed(2))}${row('Customers','customers',x=>x)}${row('Satisfaction','satisfaction',x=>x.toFixed(0)+'%')}${row('Avg. wait','wait',x=>x.toFixed(1)+'s')}${row('Items','items',x=>x)}</table><button class="button primary" id="saveBaseline">Save current as baseline</button>`);$('saveBaseline').onclick=()=>{baseline=current;localStorage.setItem('marketmaker-baseline',JSON.stringify(baseline));$('modal').classList.add('hidden')}};
try{items=JSON.parse(localStorage.getItem('marketmaker-layout'))||[];baseline=JSON.parse(localStorage.getItem('marketmaker-baseline'))}catch{items=[]}renderPalette();render();
